import * as T from './vendor/three.module.js';
import {makeWorld} from './sky-world.mjs';
import {islands,player,jump,dash,step,respawn,distance} from './sky-engine.mjs';
const $=id=>document.getElementById(id),canvas=$('scene'),dialog=$('dialog');
let renderer;try{renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});}catch(e){$('loading').hidden=true;$('error').hidden=false;throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
const world=makeWorld(),{scene}=world,camera=new T.PerspectiveCamera(55,innerWidth/innerHeight,.1,550);let yaw=0,zoom=18,pitch=.52;
let running=false,duo=false,elapsed=0,time=0,last=performance.now(),relics=[false,false,false],featherIds=new Set(),gemIds=new Set(),relay=-1,relayTime=0,boss=false,bossHP=3,bossCycle=0,won=false,toastUntil=0,chain=0,chainUntil=0,saveTime=0;
const players=[player(),player(2,8)],avatars=[world.avatar('#427f9b'),world.avatar('#b06f9d')];avatars[1].g.visible=false;const keys=new Set(),effects=[];let audio=null,sound=false;
const SAVE='bukham-shellbound-3d-v1';let saved=null;try{saved=JSON.parse(localStorage.getItem(SAVE));if(saved?.v===1)$('continue').hidden=false;}catch{}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();
function beep(freq=440,duration=.08){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.7,audio.currentTime+duration);g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');toastUntil=time+3.5;}
function burst(p,col='#ffe095',n=12){for(let i=0;i<n;i++){let m=world.ball(p.x,p.y+1,p.z,.12,col);effects.push({m,life:.65,max:.65,vx:(Math.random()-.5)*9,vy:Math.random()*8,vz:(Math.random()-.5)*9});}}
function pulseEffect(p){let m=world.ring(p.x,p.y+.3,p.z,1,'#9af6e0');effects.push({m,life:.5,max:.5,ring:true});}
function save(){if(!running)return;try{localStorage.setItem(SAVE,JSON.stringify({v:1,relics,feathers:[...featherIds],gems:[...gemIds],elapsed,checkpoint:players[0].checkpoint,duo}));$('continue').hidden=false;}catch{}}
function modal(html){keys.clear();$('dialogBody').innerHTML=html;if(!dialog.open)dialog.showModal();}
function close(){dialog.close();canvas.focus();}
$('close').onclick=close;dialog.addEventListener('close',()=>keys.clear());
function help(){modal(`<h2>Your next great escape</h2><p>Restore three sky echoes. Jump between the gold-edged platforms, race the lanterns, gather airborne feathers and break the storm guardian’s shield.</p><div class="control-grid"><div><h3>Player one</h3><p><kbd>W A S D</kbd> Move<br><kbd>Space</kbd> Jump, again for double jump<br><kbd>Shift</kbd> Air dash<br><kbd>E</kbd> Pulse / interact<br><kbd>R</kbd> Reset camera</p></div><div><h3>Player two · local co-op</h3><p><kbd>Arrow keys</kbd> Move<br><kbd>Enter</kbd> Double jump<br><kbd>/</kbd> Dash<br><kbd>.</kbd> Pulse<br>Stay together on the shared camera.</p></div></div><p>Drag the world to orbit. Scroll to zoom. Touch controls appear on small screens. Cyan pads launch you upwards. Falling returns you to your latest island.</p><p>This is an original fantasy inspired by Nigerian storytelling, not a retelling of a specific traditional tale. Solo and two-player local co-op are playable; online multiplayer is not connected.</p>`);}
$('help').onclick=help;$('titleHelp').onclick=help;
function menu(){modal(`<h2>Take a breath, sky runner.</h2><p>Your expedition saves on this device. Change your jacket, explore the world or start a fresh run.</p><div class="swatches"><button data-col="#427f9b" style="background:#427f9b" aria-label="Blue jacket"></button><button data-col="#ce7653" style="background:#ce7653" aria-label="Orange jacket"></button><button data-col="#64a68c" style="background:#64a68c" aria-label="Green jacket"></button><button data-col="#ab7ab9" style="background:#ab7ab9" aria-label="Purple jacket"></button></div><div class="actions"><button id="resume" class="gold">Keep exploring</button><button id="restart">New run</button><button id="quality">${renderer.shadowMap.enabled?'Turn shadows off':'Turn shadows on'}</button><button id="home">Title screen</button></div>`);$('resume').onclick=close;$('restart').onclick=()=>{close();start(duo);};$('quality').onclick=()=>{renderer.shadowMap.enabled=!renderer.shadowMap.enabled;scene.traverse(o=>{if(o.material)o.material.needsUpdate=true;});menu();};$('home').onclick=()=>{save();close();running=false;$('hud').hidden=true;$('title').hidden=false;};document.querySelectorAll('[data-col]').forEach(b=>b.onclick=()=>{avatars[0].body.material=world.mat(b.dataset.col);beep(500);});}
$('menu').onclick=menu;$('pause').onclick=menu;
$('audio').onclick=()=>{sound=!sound;$('audio').textContent=sound?'♫ On':'♫ Off';beep(660);};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.');}};
function start(two=false,continuing=false){duo=two;elapsed=0;relics=[false,false,false];featherIds=new Set();gemIds=new Set();relay=-1;relayTime=0;boss=false;bossHP=3;bossCycle=0;won=false;chain=0;keys.clear();Object.assign(players[0],player());Object.assign(players[1],player(2,8));if(continuing){try{let s=JSON.parse(localStorage.getItem(SAVE));if(s?.v===1){duo=!!s.duo;relics=[0,1,2].map(i=>s.relics?.[i]===true);featherIds=new Set((s.feathers||[]).filter(n=>Number.isInteger(n)&&n>=0&&n<6));gemIds=new Set((s.gems||[]).filter(n=>Number.isInteger(n)&&n>=0&&n<world.gems.length));elapsed=Number.isFinite(s.elapsed)?Math.max(0,s.elapsed):0;players.forEach(p=>{p.checkpoint=Number.isInteger(s.checkpoint)?Math.max(0,Math.min(3,s.checkpoint)):0;respawn(p);});players[1].x+=2;won=relics.every(Boolean);}}catch{}}
world.feathers.forEach(f=>f.m.visible=!featherIds.has(f.id));world.gems.forEach(g=>g.m.visible=!gemIds.has(g.id));avatars[1].g.visible=duo;world.guardian.visible=!won;world.shock.visible=false;running=true;yaw=0;zoom=duo?23:18;$('title').hidden=true;$('hud').hidden=false;$('p2status').hidden=!duo;camera.position.set(players[0].x,players[0].y+13,players[0].z+18);canvas.focus();toast(continuing?'Welcome back to the sky.':'Space twice to double jump. Shift to dash across the gaps.');save();}
$('start').onclick=()=>start();$('duo').onclick=()=>start(true);$('continue').onclick=()=>start(false,true);
function damage(p){if(p.inv>0)return;p.hearts--;p.inv=1.8;p.vy=8;p.ground=null;burst(p,'#ef8c7a');beep(130,.2);if(p.hearts<=0){respawn(p);toast('The sky catches you. Back at your checkpoint.');}}
function reward(i){if(relics[i])return;relics[i]=true;players.forEach(p=>{p.hearts=3;burst(p,'#ffe28d',30);});beep(880,.4);toast(['Echo restored! Next: the feather island.','Two echoes restored. The storm is waiting.','All echoes restored. The sky is yours!'][i]);save();if(i===2){won=true;boss=false;world.guardian.visible=false;world.shock.visible=false;let best;try{best=Number(localStorage.getItem(SAVE+'-best'))||Infinity;best=Math.min(best,elapsed);localStorage.setItem(SAVE+'-best',best);}catch{best=elapsed;}modal(`<div class="reward">✦</div><h2>The sky remembers your name.</h2><p>You restored every echo and outsmarted the storm. ${duo?'Two adventurers. One legendary expedition.':'A true sky runner.'}</p><div class="stat-box"><div><b>${format(elapsed)}</b><small>EXPEDITION TIME</small></div><div><b>${gemIds.size}</b><small>SKY GEMS</small></div><div><b>${format(best)}</b><small>PERSONAL BEST</small></div></div><div class="actions"><button id="explore" class="gold">Explore freely</button><button id="again">Beat your time</button></div>`);$('explore').onclick=close;$('again').onclick=()=>{close();start(duo);};}}
function pulse(p){if(!running||dialog.open||p.pulse>0)return;p.pulse=.45;pulseEffect(p);beep(350);if(!relics[0]&&distance(p,{x:-28,z:-47})<8&&relay<0){relay=0;relayTime=32;toast('Lantern relay! Pulse the glowing lanterns in order.');}
if(relay>=0&&distance(p,world.lanterns[relay])<4){burst({...world.lanterns[relay],y:5});relay++;relayTime+=3;if(relay===3){relay=-1;reward(0);}else toast('Lantern lit! Follow the next golden beacon.');}
if(distance(p,{x:0,z:-166})<9&&!relics[2]){if(!relics[0]||!relics[1])toast('Restore the lantern and feather echoes first.');else if(!boss){boss=true;bossCycle=0;bossHP=3;toast('Jump over the red wave. Pulse the gold core when its shield opens!');}else if(bossCycle%6>3.4){bossHP--;bossCycle=Math.floor(bossCycle/6)*6+6;burst({x:0,y:13,z:-166},'#ffdd8a',25);beep(700,.2);if(bossHP<=0)reward(2);else toast(`${bossHP} shield cores left!`);}else toast('Shield closed. Wait for gold, then pulse.');}
if(distance(p,{x:0,z:-5})<5)toast('The tortoise’s challenge: share the path, not just the prize. Follow the golden platforms.');}
function act(i,kind){if(!running||dialog.open||(i===1&&!duo))return;const p=players[i];if(kind==='jump'&&jump(p)){burst(p,'#b4ffe9',5);beep(p.jumps===2?600:420);}if(kind==='dash'&&dash(p)){burst(p,'#ffc781',8);beep(220,.1);}if(kind==='pulse')pulse(p);}
const controls={ ' ': [0,'jump'],shift:[0,'dash'],e:[0,'pulse'],enter:[1,'jump'],'/':[1,'dash'],'.':[1,'pulse']};
addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(dialog.open)return;if([' ','arrowup','arrowdown','arrowleft','arrowright','enter','/'].includes(k)&&running)e.preventDefault();keys.add(k);if(!e.repeat&&controls[k])act(...controls[k]);if(k==='r')yaw=0;if(k==='escape'&&running)menu();});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();if(running&&!dialog.open)menu();});
for(const b of document.querySelectorAll('[data-move]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.move);}
for(const [id,kind] of [['tjump','jump'],['tdash','dash'],['tpulse','pulse']])$(id).onpointerdown=e=>{e.preventDefault();act(0,kind);};
let drag=null;canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;yaw-=(e.clientX-drag.x)*.006;pitch=Math.max(.22,Math.min(1.15,pitch+(e.clientY-drag.y)*.004));drag={x:e.clientX,y:e.clientY};};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(12,Math.min(35,zoom+e.deltaY*.015));},{passive:false});
function input(i){let x=(keys.has(i?'arrowright':'d')?1:0)-(keys.has(i?'arrowleft':'a')?1:0),z=(keys.has(i?'arrowdown':'s')?1:0)-(keys.has(i?'arrowup':'w')?1:0);return{x:x*Math.cos(yaw)+z*Math.sin(yaw),z:-x*Math.sin(yaw)+z*Math.cos(yaw)};}
const format=n=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;
function target(){if(!relics[0])return relay>=0?world.lanterns[relay]:{x:-28,y:3,z:-47};if(!relics[1])return world.feathers.find(f=>!featherIds.has(f.id))||islands[2];return {x:0,y:10,z:-166};}
function hud(){let p=players[0],t=target();$('relics').textContent=relics.filter(Boolean).length+'/3';$('gems').textContent=gemIds.size;$('timer').textContent=format(elapsed);$('hearts').textContent='◆ '.repeat(p.hearts)+'◇ '.repeat(3-p.hearts);$('energy').style.width=p.energy*100+'%';$('p2status').textContent=`P2 ${'◆'.repeat(players[1].hearts)} · Dash ${Math.round(players[1].energy*100)}%`;$('district').textContent=islands[p.checkpoint].name.toUpperCase();$('quest').textContent=won?'The sky is yours':!relics[0]?(relay>=0?'Light the next lantern':'Race the lanterns'):!relics[1]?'Catch the six sky feathers':'Outsmart the storm guardian';$('detail').textContent=won?'Find the remaining gems or try a faster run.':!relics[0]?'Reach the lantern island. Pulse to start the relay.':!relics[1]?'Jump onto the raised stones. Cyan pads launch you higher.':'Jump over red shockwaves. Pulse near the core when it glows gold.';$('trial').hidden=!(relay>=0||(!relics[1]&&relics[0])||boss);$('trial').textContent=relay>=0?`${Math.ceil(relayTime)}s · Lantern ${relay+1}/3`:boss?`${bossHP} cores · ${bossCycle%6>3.4?'SHIELD OPEN · PULSE!':'Incoming wave · JUMP'}`:`${featherIds.size}/6 feathers`;
let d=distance(p,t),angle=Math.atan2(t.x-p.x,-(t.z-p.z))+yaw;let arrow=Math.cos(angle)>.5?'↑':Math.cos(angle)<-.5?'↓':Math.sin(angle)>0?'→':'←';$('compass').textContent=won?'✦ Expedition complete':`${arrow} ${Math.round(d)}m · ${!relics[0]?'Lantern echo':!relics[1]?'Sky feather':'Storm core'}`;$('prompt').textContent=won?'':d<8?(!relics[0]?'E / Pulse · light the lantern':!relics[1]?'Jump to catch the feather':'E / Pulse · challenge the guardian'):'';$('combo').textContent=time<chainUntil&&chain>1?`✧ ${chain} GEM STREAK`:'';
world.beacon.position.set(t.x,(t.y||0)+10,t.z);world.beacon.visible=!won;}
function update(dt){elapsed+=won?0:dt;world.platformMeshes.forEach(({p,g})=>{let old=p.x;if(p.moving)p.x=p.baseX+Math.sin(time)*2;p.deltaX=p.x-old;g.position.x=p.x;});
players.slice(0,duo?2:1).forEach((p,i)=>{const prev={x:p.x,z:p.z};if(step(p,dt,input(i),world.plats)){respawn(p);toast('Nice try! Your checkpoint kept your progress.');}if(duo&&distance(p,players[1-i])>34){p.x=prev.x;p.z=prev.z;if(time%3<dt)toast('Stay together! Your partner shares this camera.');}
for(let j=0;j<islands.length;j++){let a=islands[j];if(distance(p,a)<a.r-2&&Math.abs(p.y-a.y)<.2&&p.checkpoint!==j){p.checkpoint=j;toast(`${a.name} · checkpoint reached`);save();}}
for(const pad of world.pads){if(distance(p,pad)<1.4&&p.ground&&time>(p.padUntil||0)){p.vy=15;p.ground=null;p.jumps=1;p.padUntil=time+1;burst(p,'#9fffe9');beep(800,.15);}}
for(const g of world.gems)if(!gemIds.has(g.id)&&distance(p,g)<1.2&&Math.abs(p.y+1-g.y)<1.8){gemIds.add(g.id);g.m.visible=false;chain=time<chainUntil?chain+1:1;chainUntil=time+3;burst(p,'#ffe095',5);beep(500+Math.min(chain,8)*70);}
for(const f of world.feathers)if(!featherIds.has(f.id)&&distance(p,f)<1.1&&Math.abs(p.y+1.3-f.y)<1.2){featherIds.add(f.id);f.m.visible=false;burst(p,'#9affdf');beep(900,.15);toast(`Sky feather ${featherIds.size}/6`);if(featherIds.size===6)reward(1);}
const a=avatars[i];a.g.position.set(p.x,p.y,p.z);a.g.rotation.y=Math.atan2(p.dx,p.dz);const moving=Math.hypot(input(i).x,input(i).z)>.1;a.limbs.forEach((l,k)=>l.rotation.x=p.ground?(moving?Math.sin(time*14+k%2*Math.PI+i)*.65:0):k%2?.45:-.5);a.cape.rotation.x=.15+Math.sin(time*8)*.06+(p.dash>0?.8:0);a.g.visible=p.inv>0?Math.floor(time*12)%2===0:true;if(p.dash>0&&Math.random()<.7)burst(p,'#d7ffed',1);
});
if(relay>=0){relayTime-=dt;if(relayTime<=0){relay=-1;toast('Time slipped away! Pulse at the island entrance to retry.');}}
if(boss){bossCycle+=dt;let phase=bossCycle%6;world.shock.visible=phase<3.4;let radius=phase*7;world.shock.scale.set(radius,radius,radius);world.halo.material=world.mat(phase>3.4?'#ffd47d':'#ee7d7d',true);for(const p of players.slice(0,duo?2:1))if(phase<3.4&&Math.abs(distance(p,{x:0,z:-166})-radius)<.8&&p.y<11.05)damage(p);}
world.lanterns.forEach((l,i)=>{l.light.material=world.mat(relics[0]||i<relay?'#9bffdd':i===relay?'#ffce73':'#729eaa',true);l.light.scale.setScalar(i===relay?1.2+Math.sin(time*5)*.1:1);});
if(time-saveTime>4){saveTime=time;save();}hud();}
const look=new T.Vector3(),wanted=new T.Vector3();
function frame(now){const dt=Math.min(.033,(now-last)/1000);last=now;time+=dt;requestAnimationFrame(frame);if(running&&!dialog.open)update(dt);
for(const e of effects){if(!dialog.open)e.life-=dt;if(e.ring){e.m.scale.setScalar(1+(1-e.life/e.max)*6);}else{e.m.position.x+=e.vx*dt;e.m.position.y+=e.vy*dt;e.m.position.z+=e.vz*dt;e.vy-=dt*12;e.m.scale.setScalar(Math.max(.01,e.life/e.max));}}for(let i=effects.length-1;i>=0;i--)if(effects[i].life<=0){scene.remove(effects[i].m);effects[i].m.geometry.dispose();effects.splice(i,1);}
world.gems.forEach(g=>{g.m.rotation.y=time*1.5;g.m.position.y=g.y+Math.sin(time*2+g.id)*.15;});world.feathers.forEach(f=>{f.m.rotation.y=time;f.m.position.y=f.y+Math.sin(time*2+f.id)*.25;});world.guardian.rotation.y=time*.45;world.guardian.position.y=13+Math.sin(time)*.4;
world.clouds.forEach((c,i)=>c.position.x+=Math.sin(i)*dt*.12);
if(time>toastUntil)$('toast').classList.remove('show');
if(running){let p=players[0],q=duo?players[1]:p;look.set((p.x+q.x)/2,(p.y+q.y)/2+1.7,(p.z+q.z)/2);let dist=duo?Math.max(zoom,distance(p,q)*1.1+12):zoom;wanted.set(look.x+Math.sin(yaw)*dist*Math.cos(pitch),look.y+Math.sin(pitch)*dist,look.z+Math.cos(yaw)*dist*Math.cos(pitch));camera.position.lerp(wanted,1-Math.exp(-dt*7));camera.lookAt(look);}else{camera.position.set(37+Math.sin(time*.08)*8,25,34+Math.cos(time*.08)*4);camera.lookAt(-5,1,-12);}
renderer.render(scene,camera);}
$('loading').hidden=true;$('title').hidden=false;requestAnimationFrame(frame);
addEventListener('pagehide',save);
